import{_ as t,o as a,c as e,aN as r}from"./chunks/framework.D31DlcCL.js";const n="/img/edu-openclaw-1-1.svg",s="/img/edu-openclaw-1-2.svg",l="/img/edu-openclaw-1-3.svg",c="/img/edu-openclaw-1-4.svg",p="/img/edu-openclaw-1-5.svg",i="/img/edu-openclaw-1-6.svg",g="/img/edu-openclaw-1-7.svg",d="/img/edu-openclaw-1-8.svg",f=JSON.parse('{"title":"小学生教程①：30秒装上你的“新同桌”OpenClaw","description":"","frontmatter":{"title":"小学生教程①：30秒装上你的“新同桌”OpenClaw","date":"2026-02-28T20:00:00.000Z","categories":["杂谈"],"tags":["小学生教程","OpenClaw","智能助手"]},"headers":[],"relativePath":"posts/openclaw-edu-1.md","filePath":"posts/openclaw-edu-1.md","lastUpdated":null}'),h={name:"posts/openclaw-edu-1.md"};function u(m,o,b,_,q,k){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="小学生教程1-30秒装上你的-新同桌-openclaw" tabindex="-1">小学生教程①：30秒装上你的“新同桌”OpenClaw <a class="header-anchor" href="#小学生教程1-30秒装上你的-新同桌-openclaw" aria-label="Permalink to &quot;小学生教程①：30秒装上你的“新同桌”OpenClaw&quot;">​</a></h1><p>嘿！想不想在电脑里藏一个<strong>超酷的“新同桌”</strong>？🤖 它不是那种只会复读的复读机， 而是一个能帮你<strong>整理书包、找资料、甚至画画</strong>的小管家！ 它的名字叫 <strong>OpenClaw</strong>（你可以叫它“小螃蟹”🦀）。</p><p>安装它就像<strong>吃掉一块巧克力</strong>那么简单！😋 快跟着我这几步，30秒就能搞定：</p><h3 id="🏁-第一步-找到电脑的-秘密窗口" tabindex="-1">🏁 第一步：找到电脑的“秘密窗口” <a class="header-anchor" href="#🏁-第一步-找到电脑的-秘密窗口" aria-label="Permalink to &quot;🏁 第一步：找到电脑的“秘密窗口”&quot;">​</a></h3><p>在电脑左下角点一下，搜“PowerShell”， 你会看到一个<strong>蓝色的大盒子</strong>，点开它！🖥️</p><blockquote><p><img src="'+n+'" alt="图片1：手绘蓝色电脑窗口，旁边有个小螃蟹在招手"><strong>图注：看！就是这个蓝盒子，我们要在这里变魔术啦！🌀</strong></p></blockquote><h3 id="🪄-第二步-念动-变身咒语" tabindex="-1">🪄 第二步：念动“变身咒语” <a class="header-anchor" href="#🪄-第二步-念动-变身咒语" aria-label="Permalink to &quot;🪄 第二步：念动“变身咒语”&quot;">​</a></h3><p>把下面这串<strong>魔法代码</strong>复制下来， 然后在这个蓝色窗口里，按一下键盘上的 <strong>Enter（回车）</strong>： <code>iwr -useb https://openclaw.ai/install.ps1 | iex</code></p><blockquote><p><img src="'+s+'" alt="图片2：代码被彩虹色圈住，箭头指向回车键"><strong>图注：别害怕这些长长的字母，它们是小螃蟹的“变身药水”！🧪</strong></p></blockquote><h3 id="⏳-第三步-小螃蟹正在赶来" tabindex="-1">⏳ 第三步：小螃蟹正在赶来！ <a class="header-anchor" href="#⏳-第三步-小螃蟹正在赶来" aria-label="Permalink to &quot;⏳ 第三步：小螃蟹正在赶来！&quot;">​</a></h3><p>你会看到一串串小字符在<strong>飞快跳舞</strong>， 就像在下载超好玩的新游戏一样！💃 等它跑完了，小螃蟹就住进你的电脑啦！</p><blockquote><p><img src="'+l+'" alt="图片3：进度条变成了一个正在跑步的小螃蟹"><strong>图注：加油！小螃蟹正背着书包往你的电脑里跑呢！🏃‍♂️</strong></p></blockquote><h3 id="🏠-第四步-推开新家的大门" tabindex="-1">🏠 第四步：推开新家的大门 <a class="header-anchor" href="#🏠-第四步-推开新家的大门" aria-label="Permalink to &quot;🏠 第四步：推开新家的大门&quot;">​</a></h3><p>在黑窗口里输入：<code>openclaw onboard</code> 你会看到一个<strong>超级漂亮的新页面</strong>弹出来， 这就是小螃蟹的“指挥部”！🎨</p><blockquote><p><img src="'+c+'" alt="图片4：屏幕上弹出一个五彩斑斓的对话框"><strong>图注：哇！指挥部好酷！我们要开始正式认识它啦！✨</strong></p></blockquote><h3 id="🔑-第五步-给它一个-大脑" tabindex="-1">🔑 第五步：给它一个“大脑” <a class="header-anchor" href="#🔑-第五步-给它一个-大脑" aria-label="Permalink to &quot;🔑 第五步：给它一个“大脑”&quot;">​</a></h3><p>小螃蟹需要一个**“智慧芯片”<strong>（也就是 API Key）， 让爸爸妈妈帮你申请一个放在里面， 它就会瞬间变得比</strong>百科全书**还要聪明！🧠</p><blockquote><p><img src="'+p+'" alt="图片5：小螃蟹把一个发光的灯泡放进脑壳里"><strong>图注：装上智慧芯片，小螃蟹就能听懂你所有的指令啦！💡</strong></p></blockquote><h3 id="💬-第六步-说声-你好" tabindex="-1">💬 第六步：说声“你好”！ <a class="header-anchor" href="#💬-第六步-说声-你好" aria-label="Permalink to &quot;💬 第六步：说声“你好”！&quot;">​</a></h3><p>在网页中间的输入框里，随便打个字： “你好呀，你是谁？” 看看它会怎么<strong>调皮地回答</strong>你？😜</p><blockquote><p><img src="'+i+'" alt="图片6：对话框里出现了一行字：我是你的全能助理小螃蟹！"><strong>图注：看！它真的会说话！快跟它交个朋友吧！🤝</strong></p></blockquote><h3 id="📱-第七步-连上你的手机" tabindex="-1">📱 第七步：连上你的手机 <a class="header-anchor" href="#📱-第七步-连上你的手机" aria-label="Permalink to &quot;📱 第七步：连上你的手机&quot;">​</a></h3><p>让爸爸妈妈帮你点一下“Connect”， 扫一下那个<strong>黑白小方块（二维码）</strong>， 这样你在微信里也能指挥它干活啦！📱</p><blockquote><p><img src="'+g+'" alt="图片7：手机屏幕和电脑屏幕连在一起的示意图"><strong>图注：以后出门在外，也能让小螃蟹帮你查资料咯！🚀</strong></p></blockquote><h3 id="🎉-第八步-大功告成" tabindex="-1">🎉 第八步：大功告成！ <a class="header-anchor" href="#🎉-第八步-大功告成" aria-label="Permalink to &quot;🎉 第八步：大功告成！&quot;">​</a></h3><p>恭喜你！现在你已经拥有了<strong>全班最厉害</strong>的AI助手！ 不管是查单词、搜图片，它都随叫随到！🎈</p><blockquote><p><img src="'+d+'" alt="图片8：一个戴着红领巾的小螃蟹在撒花庆祝"><strong>图注：安装成功！你就是科技小达人！🏆</strong></p></blockquote><hr><h3 id="🎁-本课小挑战" tabindex="-1">🎁 本课小挑战 <a class="header-anchor" href="#🎁-本课小挑战" aria-label="Permalink to &quot;🎁 本课小挑战&quot;">​</a></h3><p><strong>第一关：</strong> 成功打开小螃蟹的页面，截一张图发给爸爸妈妈看！ <strong>第二关：</strong> 对小螃蟹说：“帮我画一只正在吃冰淇淋的猫”，看它能不能做到？ <strong>打卡方式：</strong> 把截图发在评论区，看看谁的小螃蟹最聪明！👇</p>',30)])])}const P=t(h,[["render",u]]);export{f as __pageData,P as default};
